component_data_script:
rows = props.get("steps") or []
if isinstance(rows, str):
	try:
		rows = json.loads(rows)
	except Exception:
		rows = [line for line in rows.split("\n") if line.strip()]
if not isinstance(rows, list):
	rows = []

steps = []
for raw in rows:
	parts = [part.strip() for part in str(raw).split("|")]
	if not parts or not parts[0]:
		continue
	while len(parts) < 4:
		parts.append("")
	steps.append({"name": parts[0], "href": parts[1] or "#", "date": parts[2], "datetime": parts[3]})
for i in range(len(steps)):
	step = steps[i]
	step["n"] = str(i + 1)
component.steps = steps
